// Get the CSV content (text)
const body = $input.item.json.body;
const csvContent = body.csv;

if (!csvContent) {
  return [{ json: { success: false, error: 'No CSV content provided' } }];
}

// Return the CSV text for parsing
return [{ json: { csvContent } }];

// Parse Asset Bank CSV format - group by operation type
// Columns (separated by ;):
// 0: Сметка/Карта (IBAN)
// 1: Дата (DD.MM.YYYY)
// 2: Дб/Кр
// 3: Сума
// 4: Валута
// 5-6: BIC/IBAN на наредител
// 7-8: Тип/Име на наредител
// 9-10: BIC/IBAN на получател
// 11-12: Тип/Име на получател
// 13: Тип операция
// 14-15: Основание 1/2
// 17: Референция

const csvContent = $input.item.json.csvContent;
const lines = csvContent.split('\n');

const rawTransactions = [];
const processedRefs = new Set();

// Skip header row, parse all transactions first
for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  const cols = line.split(';');
  if (cols.length < 14) continue;

  const iban = cols[0].trim();
  const dateStr = cols[1].trim();
  const typeRaw = cols[2].trim().toLowerCase();
  const amountStr = cols[3].trim();
  const currency = cols[4].trim();
  const senderName = cols[8] ? cols[8].trim() : '';
  const receiverName = cols[12] ? cols[12].trim() : '';
  const operationType = cols[13] ? cols[13].trim() : '';
  const purpose1 = cols[14] ? cols[14].trim() : '';
  const purpose2 = cols[15] ? cols[15].trim() : '';
  const reference = cols[17] ? cols[17].trim() : '';

  // Skip if not main IBAN
  if (!iban.startsWith('BG')) continue;

  // Skip duplicates by reference
  if (reference && processedRefs.has(reference)) continue;
  if (reference) processedRefs.add(reference);

  // Parse date
  const dateParts = dateStr.split('.');
  const isoDate = dateParts.length === 3 
    ? `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`
    : dateStr;

  // Parse amount
  const cleanAmount = amountStr.replace(/\s/g, '').replace(',', '.');
  const amount = parseFloat(cleanAmount) || 0;

  // Determine debit/credit
  const isDebit = typeRaw.includes('дебит') || typeRaw.includes('debit');
  const type = isDebit ? 'debit' : 'credit';

  rawTransactions.push({
    rowIndex: i,
    date: isoDate,
    reference,
    description: operationType || purpose1,
    operationType: operationType.toLowerCase(),
    type,
    amount,
    currency: currency || 'EUR',
    iban,
    senderName,
    receiverName,
    purpose: (purpose1 + ' ' + purpose2).trim(),
    purpose1,
    purpose2
  });
}

// ========== Group by operation type ==========
const finalTransactions = [];
let interestTotal = 0;
let interestCount = 0;
let principalTotal = 0;
let principalCount = 0;
let feesTotal = 0;
let feesCount = 0;
let skippedCount = 0;
let firstInterestDate = null, lastInterestDate = null;
let firstPrincipalDate = null, lastPrincipalDate = null;
let firstFeeDate = null, lastFeeDate = null;

rawTransactions.forEach(tx => {
  const opType = tx.operationType.toLowerCase();

  // Skip: "Усвояване на кредит" and "Издължаване на кредит"
  if (opType.includes('усвояване на кредит') || opType.includes('издължаване на кредит')) {
    skippedCount++;
    return;
  }

  // Group: "Банково вземане лихва"
  if (opType.includes('банково вземане лихва')) {
    interestTotal += tx.amount;
    interestCount++;
    if (!firstInterestDate || tx.date < firstInterestDate) firstInterestDate = tx.date;
    if (!lastInterestDate || tx.date > lastInterestDate) lastInterestDate = tx.date;
    return;
  }

  // Group: "Банково вземане главница"
  if (opType.includes('банково вземане главница')) {
    principalTotal += tx.amount;
    principalCount++;
    if (!firstPrincipalDate || tx.date < firstPrincipalDate) firstPrincipalDate = tx.date;
    if (!lastPrincipalDate || tx.date > lastPrincipalDate) lastPrincipalDate = tx.date;
    return;
  }

  // Group: "Автоматична такса"
  if (opType.includes('автоматична такса')) {
    feesTotal += tx.amount;
    feesCount++;
    if (!firstFeeDate || tx.date < firstFeeDate) firstFeeDate = tx.date;
    if (!lastFeeDate || tx.date > lastFeeDate) lastFeeDate = tx.date;
    return;
  }

  // Keep separate: "Кредитен превод", "Картови транзакции", "Вътрешно банков превод"
  let displayName = tx.description || tx.purpose1;
  let counterpartyName = tx.type === 'debit' ? tx.receiverName : tx.senderName;

  // Extract invoice reference if present
  let invoiceRef = '';
  const invoiceMatch = tx.purpose.match(/(?:фактура|ф-ра|invoice|inv)[\s#:]*([\d\/]+)/i);
  if (invoiceMatch) invoiceRef = invoiceMatch[1];

  finalTransactions.push({
    date: tx.date,
    reference: tx.reference,
    description: tx.description,
    displayName: counterpartyName || displayName,
    operationType: tx.operationType,
    type: tx.type,
    amount: tx.amount,
    currency: tx.currency,
    iban: tx.iban,
    counterpartyName,
    invoiceRef,
    purpose: tx.purpose,
    objectId: null,
    objectName: null,
    technicianId: null,
    technicianName: null,
    status: 'unmatched'
  });
});

// Add grouped interest if any
if (interestTotal > 0) {
  finalTransactions.push({
    date: lastInterestDate || new Date().toISOString().split('T')[0],
    reference: 'INTEREST-' + (lastInterestDate || '').replace(/-/g, ''),
    description: `Лихви (${interestCount} бр.)`,
    displayName: `Лихви (${interestCount} бр.)`,
    operationType: 'Банково вземане лихва',
    type: 'debit',
    amount: Math.round(interestTotal * 100) / 100,
    currency: 'EUR',
    iban: rawTransactions[0]?.iban || '',
    counterpartyName: 'Банка',
    invoiceRef: '',
    purpose: `Обединени лихви за периода ${firstInterestDate} - ${lastInterestDate}`,
    objectId: null,
    objectName: null,
    technicianId: null,
    technicianName: null,
    status: 'unmatched',
    isGrouped: true
  });
}

// Add grouped principal if any
if (principalTotal > 0) {
  finalTransactions.push({
    date: lastPrincipalDate || new Date().toISOString().split('T')[0],
    reference: 'PRINCIPAL-' + (lastPrincipalDate || '').replace(/-/g, ''),
    description: `Главници по кредити (${principalCount} бр.)`,
    displayName: `Главници по кредити (${principalCount} бр.)`,
    operationType: 'Банково вземане главница',
    type: 'debit',
    amount: Math.round(principalTotal * 100) / 100,
    currency: 'EUR',
    iban: rawTransactions[0]?.iban || '',
    counterpartyName: 'Банка',
    invoiceRef: '',
    purpose: `Обединени главници за периода ${firstPrincipalDate} - ${lastPrincipalDate}`,
    objectId: null,
    objectName: null,
    technicianId: null,
    technicianName: null,
    status: 'unmatched',
    isGrouped: true
  });
}

// Add grouped fees if any
if (feesTotal > 0) {
  finalTransactions.push({
    date: lastFeeDate || new Date().toISOString().split('T')[0],
    reference: 'FEES-' + (lastFeeDate || '').replace(/-/g, ''),
    description: `Банкови такси (${feesCount} бр.)`,
    displayName: `Банкови такси (${feesCount} бр.)`,
    operationType: 'Автоматична такса',
    type: 'debit',
    amount: Math.round(feesTotal * 100) / 100,
    currency: 'EUR',
    iban: rawTransactions[0]?.iban || '',
    counterpartyName: 'Банка',
    invoiceRef: '',
    purpose: `Обединени банкови такси за периода ${firstFeeDate} - ${lastFeeDate}`,
    objectId: null,
    objectName: null,
    technicianId: null,
    technicianName: null,
    status: 'unmatched',
    isGrouped: true
  });
}

// Sort by date descending
finalTransactions.sort((a, b) => b.date.localeCompare(a.date));

// Calculate totals
const totalDebit = finalTransactions.filter(t => t.type === 'debit').reduce((sum, t) => sum + t.amount, 0);
const totalCredit = finalTransactions.filter(t => t.type === 'credit').reduce((sum, t) => sum + t.amount, 0);
const netChange = Math.round((totalCredit - totalDebit) * 100) / 100;

return [{ 
  json: { 
    success: true, 
    data: {
      transactions: finalTransactions,
      count: finalTransactions.length,
      totalDebit: Math.round(totalDebit * 100) / 100,
      totalCredit: Math.round(totalCredit * 100) / 100,
      groupedInterest: Math.round(interestTotal * 100) / 100,
      groupedInterestCount: interestCount,
      groupedPrincipal: Math.round(principalTotal * 100) / 100,
      groupedPrincipalCount: principalCount,
      groupedFees: Math.round(feesTotal * 100) / 100,
      groupedFeesCount: feesCount,
      skippedTransactions: skippedCount,
      netChange
    }
  } 
}];
